package com.chris.uberratebanner;
import android.app.Activity;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public final class BannerUi{private BannerUi(){} public static int translucent(int c){return Color.argb(204,Color.red(c),Color.green(c),Color.blue(c));}
 public static void show(Activity a,FrameLayout host,RideRecord r){if(host==null||r==null)return;TextView b=new TextView(a);b.setText(String.format(Locale.US,"$%.2f/hr  •  $%.2f  •  %d min",r.hourly,r.payout,r.totalMinutes));b.setTextColor(RateColors.textForHourly(a,r.hourly));b.setTextSize(15);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setGravity(Gravity.CENTER);b.setBackground(UiKit.rounded(translucent(RateColors.forHourly(a,r.hourly)),11,a));int h=Math.max(UiKit.dp(a,28),Math.round(a.getResources().getDisplayMetrics().densityDpi*.25f));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,h,Gravity.TOP);p.leftMargin=UiKit.dp(a,16);p.rightMargin=UiKit.dp(a,16);p.topMargin=SafeArea.bannerTop(a);host.addView(b,p);b.postDelayed(()->{try{host.removeView(b);}catch(Exception ignored){}},AppSettings.bannerDurationMs(a));}}
